function cdProjectListRefresh(){const d=clientDesk.data,results=document.querySelector('[data-client-project-results]');if(!d||!results)return;const p=d.projects.find(row=>row.id===clientDesk.id);results.innerHTML=cdProjectRows(cdVisibleRows(d),p,d);}
function clientDeskPanel(){if(typeof clientReplyTemplatesSync==='function')clientReplyTemplatesSync();if(typeof clientProjectScreenCapture==='function')clientProjectScreenCapture();if(typeof clientProjectScreenRestore==='function')requestAnimationFrame(clientProjectScreenRestore);if(typeof clientScheduleEnsure==='function')queueMicrotask(clientScheduleEnsure);if(typeof clientDeliveryEnsure==='function')queueMicrotask(clientDeliveryEnsure);requestAnimationFrame(cdRestoreDrafts);requestAnimationFrame(cdFollowUpClockSchedule);requestAnimationFrame(cdApplyTarget);const d=clientDesk.data,p=d?.projects.find(p=>p.id===clientDesk.id),today=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const all=d?.projects||[],active=all.filter(p=>p.stage!=='archived'),unresolved=active.reduce((n,p)=>n+p.messages.filter(m=>m.author==='customer'&&!m.resolved).length,0),due=active.filter(p=>p.nextContactDate&&p.nextContactDate<=today).length;const rows=cdVisibleRows(d);
  return `<section class="client-desk cdx" data-project-open="${!!(p||clientDesk.id==='new')}"><header class="cd-heading"><div><span class="cd-eyebrow" aria-hidden="true">PULSE · Client desk</span><h1>고객 관리</h1><p>접수부터 시안 확인, 납품 뒤 질문까지 한 줄로 이어요.</p></div><div class="cd-metrics" role="group" aria-label="목록 거르기"><button type="button" data-client-quick="" aria-pressed="${!clientDesk.quick}"><strong>${active.length}</strong><span>진행 중</span></button><button type="button" data-client-quick="requests" aria-pressed="${clientDesk.quick==='requests'}"${unresolved?' data-tone="alert"':''}><strong>${unresolved}</strong><span>답할 요청</span></button><button type="button" data-client-quick="contact" aria-pressed="${clientDesk.quick==='contact'}"${due?' data-tone="due"':''}><strong data-client-followup-due-count>${due}</strong><span>오늘까지 연락</span></button></div></header>${clientDesk.error?`<p role="alert" class="cd-error">${escape(clientDesk.error)}</p>`:''}<div class="cd-toolbar"><button type="button" class="cd-search-launch" data-client-search-action="open">${cdIcons.search}<span>프로젝트 통합검색</span><small>메모 · 글 · 장면 · 자료</small></button><button type="button" class="cd-button cd-icon-button" data-client="refresh" title="새로 불러오기">${cdIcons.refresh}<span class="cps-sr">새로 불러오기</span></button>${d?.canImport?cdButton('PULSE 접수함','intake'):''}${d?.canWrite?cdButton(cdIcons.plus+'<span class="cd-label">프로젝트 접수</span>','new'):''}</div>${clientDesk.loading?'<p role="status" class="cd-loading">프로젝트를 불러오고 있어요.</p>':''}${!d?'':`<div class="cd-layout">${typeof clientProjectListStart==='function'?clientProjectListStart(p):'<aside><div class="cd-list">'}<div class="cd-list-tools"><label class="cd-search"><span class="cps-sr">프로젝트 찾기</span>${cdIcons.search}<input type="search" data-client-search value="${escape(clientDesk.search)}" placeholder="고객 · 프로젝트 · 접수번호" autocomplete="off"></label><div class="cd-filter" role="group" aria-label="표시할 프로젝트"><button type="button" data-client-filter-value="active" aria-pressed="${clientDesk.filter!=='all'}">진행 중 <b>${active.length}</b></button><button type="button" data-client-filter-value="all" aria-pressed="${clientDesk.filter==='all'}">보관 포함 <b>${all.length}</b></button></div><p class="cd-quick-note" data-client-quick-note${clientDesk.quick?'':' hidden'}>${cdQuickNote()}</p></div><div class="cd-project-results" data-client-project-results>${cdProjectRows(rows,p,d)}</div></div></aside><div class="cd-detail">${p||clientDesk.id==='new'?cdDetail(p,d):cdWelcome(d)}</div></div>`}</section>`;
}
function cdDetail(p,d){const row=p||{title:'',customerName:'',ownerId:state.user.id,stage:'received'},readOnly=!d.canWrite||p&&p.ownerId!==state.user.id&&!['admin','manager'].includes(state.user.role);const panels=[['startup',p&&typeof clientStartupPanel==='function'?clientStartupPanel(p):''],['progress',p&&typeof clientProgressUpdatePanel==='function'?clientProgressUpdatePanel(p):''],['materials',p&&typeof clientMaterialsPanel==='function'?clientMaterialsPanel(p):''],['kickoff',p&&typeof clientKickoffPanel==='function'?clientKickoffPanel(p):''],['changes',p&&typeof clientChangesPanel==='function'?clientChangesPanel(p):''],['requests',p&&typeof clientSceneRequestsPanel==='function'?clientSceneRequestsPanel(p):''],['schedule',p&&typeof clientSchedulePanel==='function'?clientSchedulePanel(p):''],['delivery',(p&&typeof clientDeliveryPanel==='function'?clientDeliveryPanel(p):'')+(p&&typeof clientDeliveryArchivePanel==='function'?clientDeliveryArchivePanel(p):'')],['closeout',p&&typeof clientCloseoutPanel==='function'?clientCloseoutPanel(p):''],['followup',p?cdFollowUp(p):''],['record',`<form id="client-project-record-${escape(p?.id||'new')}" data-client-form="project" class="cd-card" tabindex="-1"><header><div><span class="cd-eyebrow">${p?'프로젝트 기록':'새 프로젝트'}</span><h2>${escape(p?.title||'고객이 부탁한 일을 적어 주세요')}</h2></div>${p?`<span class="cd-tag">${escape(d.stages[p.stage])}</span>`:''}</header><fieldset ${readOnly?'disabled':''}><legend>고객에게 보이는 것</legend><div class="cd-fields">${cdField('프로젝트 이름','title',row.title,'text',160)}${cdField('고객 이름','customerName',row.customerName,'text',100)}<label class="cd-field">진행 상태<select name="stage">${Object.entries(d.stages).map(([key,label])=>`<option value="${key}" ${key===row.stage?'selected':''}>${label}</option>`).join('')}</select></label>${cdField('합의한 전달일','dueDate',row.dueDate,'date')}${cdField('다음 할 일','nextStep',row.nextStep,'textarea',600)}${cdField('고객이 부탁한 일','summary',row.summary,'textarea')}${cdField('합의한 범위와 수정 조건','terms',row.terms,'textarea')}</div><h3 class="cd-legend">우리끼리 보는 것</h3><div class="cd-fields">${cdField('연락처','contact',row.contact,'text',300)}${cdField('다음 연락일','nextContactDate',row.nextContactDate,'date')}<label class="cd-field">담당자<select name="ownerId">${(d.members.some(m=>m.id===row.ownerId)?d.members:[...d.members,{id:row.ownerId,name:row.ownerName||'담당자'}]).map(m=>`<option value="${m.id}" ${m.id===row.ownerId?'selected':''}>${escape(m.name)}</option>`).join('')}</select></label><label class="cd-field">내부 검토자<select name="reviewerId"><option value="">없음</option>${(d.reviewers||[]).filter(m=>m.id!==row.ownerId).map(m=>`<option value="${m.id}" ${m.id===row.reviewerId?'selected':''}>${escape(m.name)}</option>`).join('')}</select><small>정하면 그 사람도 이 프로젝트의 기록과 시안을 보고 검토해요.</small></label>${cdField('내부 메모','internalNotes',row.internalNotes,'textarea')}</div>${p?.receiptId?`<p>접수번호 <code>${escape(p.receiptId)}</code><br>고객 희망일: ${escape(p.intake?.requestedDeadline||'없음')} · 아직 합의한 날짜는 아니에요.</p>`:''}${!readOnly?'<button type="submit" class="cd-button cd-primary">저장</button>':''}</fieldset></form>`],['intake',cdIntake(p)],['lounge',p?`<section class="cd-card"><h2>고객 초대 링크</h2><p>고객은 이 링크로 가입 없이 들어와 일정·자료·시안과 우리가 고객에게 쓴 답변을 봐요. 링크는 7일 동안 쓸 수 있고, 새로 만들면 이전 링크는 닫혀요.</p><div class="cd-toolbar">${!readOnly&&p.stage!=='archived'?cdButton('초대 링크 만들기','invite')+cdButton('링크 닫기','revoke'):''}${cdButton('동료에게 알릴 글 복사','share')}</div>${clientDesk.invite?`<div class="cd-invite"><label class="cd-field">고객에게 보낼 링크<input readonly value="${escape(clientDesk.invite)}"></label>${cdButton('링크 복사','copy-invite')}<a href="${escape(clientDesk.invite)}" target="_blank" rel="noopener noreferrer">고객 화면 열기 ↗</a>${['localhost','127.0.0.1'].includes(location.hostname)?'<p>지금 주소는 이 컴퓨터에서만 열려요. 고객에게는 운영 주소로 바꿔서 보내 주세요.</p>':''}</div>`:''}</section>`:''],['versions',p?`<section class="cd-card"><h2>시안과 최종본</h2><div class="cd-versions">${p.versions.map(cdVersion).join('')||'<p>아직 올린 시안이 없어요.</p>'}</div>${readOnly||p.stage==='archived'?'':`<details><summary>새 시안 올리기</summary><form data-client-form="version"><div class="cd-fields">${cdField('버전 이름','label','','text',120)}<label class="cd-field">종류<select name="kind"><option value="preview">고객이 볼 시안</option><option value="final">최종본(납품 준비를 거치지 않고 바로)</option></select></label>${cdField('링크(https)','url','','url',2000)}<label class="cd-field">또는 파일 올리기<input type="file" name="file" accept="video/mp4,video/webm,image/png,image/jpeg"><small>MP4 · WebM · PNG · JPEG, 100MB까지</small></label>${cdField('사용 안내(최종본이면 꼭)','guide','','textarea',1000)}</div><p>최종본은 고객이 승인한 시안이 있어야 올릴 수 있어요. 보통은 「납품」에서 파일을 검사해 올려요. 링크를 넣을 땐 고객이 열 수 있는지 먼저 봐 주세요.</p><button type="submit" class="cd-button cd-primary">고객에게 보이기</button></form></details>`}</section>`:''],['messages',p?`<section id="client-requests-${escape(p.id)}" class="cd-card" tabindex="-1"><h2>대화</h2>${p.messages.map(m=>`<article id="client-message-${m.id}" tabindex="-1" class="cd-message ${m.visibility==='internal'?'internal':''}"><div><strong>${escape(m.authorName)}</strong><span>${m.visibility==='internal'?'우리끼리':m.author==='customer'?'고객':'고객에게'} · ${escape(new Date(m.at).toLocaleString('ko-KR'))}</span></div><p>${escape(m.text)}</p>${m.seconds!==null&&m.seconds!==undefined?`<small>장면 ${m.seconds}초</small>`:''}${cdRequestActions(p,m,!d.canWrite)}</article>`).join('')||'<p>아직 주고받은 글이 없어요.</p>'}${readOnly||p.stage==='archived'?'':`<form data-client-form="message">${typeof clientReplyTemplatesButton==='function'?clientReplyTemplatesButton(p.id,'message'):''}${cdField('답변이나 메모','text','','textarea')}<label class="cd-field">누가 보나<select name="visibility"><option value="customer">고객에게 보내기</option><option value="internal">우리끼리 메모</option></select></label><button type="submit" class="cd-button">보내기</button></form>`}</section>`:'']];return typeof clientProjectScreenDetail==='function'?clientProjectScreenDetail(p,d,panels):panels.map(([,html])=>html).join('');}
async function cdMutate(path,body,clearDraft=null){
  const stamp=cdSession(),draftRevision=clientDesk.draftRevisions[clearDraft]||0;if(!stamp.userId||clientDesk.userId!==stamp.userId||clientDesk.busy)return;
  clientDesk.busy=true;
  try{
    const result=await api(path,body);if(!cdSessionCurrent(stamp))return;
    cdClearSavedDraft(clearDraft,draftRevision);
    if(path==='/api/client-projects'&&clearDraft==='new:project:'&&result.project?.id&&Object.hasOwn(clientDesk.drafts,clearDraft)){
      const createdKey=result.project.id+':project:';
      if(!Object.hasOwn(clientDesk.drafts,createdKey)){
        clientDesk.drafts[createdKey]=clientDesk.drafts[clearDraft];clientDesk.draftRevisions[createdKey]=clientDesk.draftRevisions[clearDraft]||0;
        delete clientDesk.drafts[clearDraft];delete clientDesk.draftRevisions[clearDraft];
      }
    }
    clientDesk.id=result.project?.id||clientDesk.id;
    clientDesk.invite=result.invite?location.origin+'/pulse-app/#invite='+result.invite:null;
    await clientDeskLoad();return result;
  }catch(error){if(cdSessionCurrent(stamp)){clientDesk.error=error.message;notify(error.message);}}
  finally{if(cdSessionCurrent(stamp))clientDesk.busy=false;}
}
document.addEventListener('input',cdRememberDraft);
document.addEventListener('change',cdRememberDraft);
document.addEventListener('visibilitychange',cdFollowUpClockSchedule);
document.addEventListener('change',event=>{if(event.target.matches?.('[data-client-followup-disposition]'))cdFollowUpToggle(event.target.closest('[data-client-form="follow-up"]'));});
document.addEventListener('input',event=>{if(event.target.matches?.('[data-client-search]')){clientDesk.search=event.target.value;cdProjectListRefresh();}});
document.addEventListener('change',event=>{if(event.target.matches('[data-client-search]')){clientDesk.search=event.target.value;cdProjectListRefresh();}if(event.target.matches('[data-client-filter]')){clientDesk.filter=event.target.value;cdProjectListRefresh();}});
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-client-quick]');if(!button||!state.user||clientDesk.userId!==state.user.id||!clientDesk.data)return;const quick=button.dataset.clientQuick,next=quick&&clientDesk.quick!==quick?quick:null;clientDesk.quick=next;for(const node of document.querySelectorAll('.cd-metrics [data-client-quick]'))node.setAttribute('aria-pressed',String((node.dataset.clientQuick||null)===next));const note=document.querySelector('[data-client-quick-note]');if(note){note.innerHTML=cdQuickNote();note.hidden=!next;}cdProjectListRefresh();if(next)document.getElementById('client-project-list')?.scrollTo?.({top:0});});
document.addEventListener('click',event=>{const button=event.target.closest?.('[data-client-filter-value]');if(!button||!state.user||clientDesk.userId!==state.user.id)return;clientDesk.filter=button.dataset.clientFilterValue==='all'?'all':'active';for(const node of button.parentElement?.querySelectorAll('[data-client-filter-value]')||[])node.setAttribute('aria-pressed',String(node===button));cdProjectListRefresh();});
document.addEventListener('click',async event=>{const target=event.target.closest('[data-client]');if(!target||!state.user)return;const action=target.dataset.client,p=clientDesk.data?.projects.find(p=>p.id===clientDesk.id);try{if(action==='refresh'){clientDesk.error='';await clientDeskLoad();}else if(action==='new'||action==='select'){clientDesk.id=action==='new'?'new':target.dataset.id;clientDesk.invite=null;clientDesk.error='';clientDesk.target=null;clientDesk.targetApplied='';clientDesk.targetNavigation=null;const url=new URL(location.href);url.searchParams.set('project',clientDesk.id);for(const key of ['version','message','seconds','followUp','delivery','closeout','kickoff','changes','requests','schedule','materials','materialId','note','record','intake'])url.searchParams.delete(key);history.replaceState({},'',url);if(typeof clientProjectListSelected==='function')clientProjectListSelected();render();}else if(['invite','revoke'].includes(action)){await cdMutate('/api/client-projects/'+p.id+'/'+action,{revision:p.revision});}else if(action==='scene'){openClientWorkflowLink(target.dataset.href);}else if(action==='workflow'){await cdMutate('/api/client-workflow',{projectId:p.id,messageId:target.dataset.id,revision:p.revision,action:target.dataset.workflow});}else if(action==='resolve'){await cdMutate('/api/client-projects/'+p.id+'/resolve',{revision:p.revision,messageId:target.dataset.id});}else if(action==='copy-invite'){await navigator.clipboard.writeText(clientDesk.invite);notify('고객 링크를 복사했어요.');}else if(action==='share'){const url=location.origin+'/?tab=workroom&section=clients&project='+p.id;await navigator.clipboard.writeText(`[PULSE] ${p.title}\n담당: ${p.ownerName}\n다음 할 일: ${p.nextStep||'아직 없음'}\n${url}`);notify('동료에게 보낼 글을 복사했어요. 메신저에 붙여 넣으면 돼요.');}else if(action==='intake'){const result=await api('/api/client-intake');modal('PULSE 접수함','접수 도구로 받아 둔 파일을 확인해서 프로젝트로 가져와요.',`<div class="cd-intake">${result.receipts.length?result.receipts.map(r=>`<article><p>${escape(r.id)}<br>${escape(r.receivedAt)} · 자료 ${r.fileCount}개</p>${cdButton('가져오기','import',`data-id="${r.id}"`)}</article>`).join(''):'<p>받아 둔 접수가 없어요. PULSE 접수 동기화를 먼저 돌린 뒤 다시 열어 주세요.</p>'}</div>`);}else if(action==='import'){await cdMutate('/api/client-intake/import',{receiptId:target.dataset.id});if(!clientDesk.error)closeModal();}}catch(error){notify(error.message);}});
document.addEventListener('submit',async event=>{const form=event.target.closest('[data-client-form]');if(!form||!state.user)return;event.preventDefault();if(clientDesk.deliverySaving||clientDesk.closeoutSaving||clientDesk.kickoffSaving||clientDesk.changesSaving||clientDesk.sceneRequestsSaving||clientDesk.scheduleSaving||clientDesk.startupSaving)return;const stamp=cdSession();const p=clientDesk.data?.projects.find(p=>p.id===clientDesk.id),values=Object.fromEntries(new FormData(form)),draftKey=cdDraftKey(form),draftRevision=clientDesk.draftRevisions[draftKey]||0;const button=form.querySelector('[type="submit"]');button.disabled=true;try{if(form.dataset.clientForm==='follow-up'){await cdSaveFollowUp(form,values);return;}if(form.dataset.clientForm==='workflow')await cdMutate('/api/client-workflow',{...values,projectId:p.id,messageId:form.dataset.messageId,revision:p.revision},draftKey);if(form.dataset.clientForm==='project')await cdMutate('/api/client-projects'+(p?'/'+p.id:''),{...values,revision:p?.revision},draftKey);if(form.dataset.clientForm==='message')await cdMutate('/api/client-projects/'+p.id+'/messages',{...values,revision:p.revision},draftKey);if(form.dataset.clientForm==='version'){const file=values.file;delete values.file;if(file?.size){if(file.size>100*1024*1024)throw new Error('파일은 100MB까지만 올릴 수 있어요.');const response=await fetch('/api/client-projects/'+p.id+'/media',{method:'POST',headers:{'Content-Type':file.type,'X-CSRF-Token':state.csrf,'X-File-Name':encodeURIComponent(file.name),'X-Version-Label':encodeURIComponent(values.label),'X-Version-Kind':values.kind,'X-Version-Guide':encodeURIComponent(values.guide),'X-Project-Revision':String(p.revision)},body:file});const result=await response.json();if(!cdSessionCurrent(stamp))return;if(!response.ok)throw new Error(result.error);cdClearSavedDraft(draftKey,draftRevision);await clientDeskLoad();}else await cdMutate('/api/client-projects/'+p.id+'/versions',{...values,revision:p.revision},draftKey);}}catch(error){if(cdSessionCurrent(stamp))notify(error.message);}finally{if(cdSessionCurrent(stamp)&&button.isConnected)button.disabled=false;}});

function cdStopTargetNavigation(event){if(clientDesk.targetNavigation){clientDesk.targetNavigation.active=false;clientDesk.targetApplied=clientDesk.targetNavigation.key;}}
for(const type of ['pointerdown','wheel','touchstart','keydown'])document.addEventListener(type,cdStopTargetNavigation,{capture:true,passive:true});

function cdTargetInView(element){const rect=element?.getBoundingClientRect?.();if(!rect)return true;const main=document.getElementById('main')?.getBoundingClientRect?.(),top=Math.max(0,main?.top||0),bottom=Math.min(window.innerHeight||Infinity,main?.bottom||Infinity),height=bottom-top;return rect.top>=top&&rect.top<bottom-Math.min(48,height)&& (rect.height>height||rect.bottom<=bottom);}
function clientProjectTargetRefresh(){if(clientDesk.targetNavigation?.active)requestAnimationFrame(cdApplyTarget);}
